    const zone = root.createDiv({ cls: "myu-zone myu-prep-room" });
    zone.createDiv({ cls: "myu-whisper", text: `${PREP_WORDS.room}${room.team ? ` \xB7 ${room.team.name}` : ""}` });
    if (summary) {
      zone.createDiv({ cls: "myu-prep-text myu-prep-room-summary", text: summary });
      return;
    }
